"""Russian section about pre-call detail disclosure on identical five candidates."""
import json
from pathlib import Path


def add_policy(w):
    area=Path(__file__).resolve().parent
    d=json.loads((area/'results.json').read_text(encoding='utf8'));out=d['outcomes']
    w.page('SWE-ContextBench Lite  /  Решение о чтении','Когда редкое имя в задаче оправдывает чтение деталей',
           'На всех 99 задачах заранее зафиксированное правило воспроизвело выбор полного читателя. Экономия составила 2,46% входных токенов. Случайная выдача при той же частоте обычно достигала такой же точности.')
    w.p('В ходе записи из путей и идентификаторов прежней правки извлекали словарь. Учитывали слова минимум из четырёх символов, встречавшиеся максимум в 15% библиотеки. Пусть имя из текущей задачи встретилось среди правок одной из пяти найденных историй. Если из кратких записей по этому имени нельзя выделить ту же единственную историю, показываем подробности всех пяти. Иначе модель получает только краткие записи.')
    w.tbl(['Предъявление правок','Полных выдач','Match@1','Одна связь¹','Входные токены'],[
        [label,str(out[key]['full']),str(out[key]['any'])+'/99',str(out[key]['last'])+'/99',w.n(out[key]['prompt'])]
        for key,label in [('never','Всегда кратко'),('always','Всегда подробно'),('gate','По совпадению имени'),('random','Случайно, та же частота')]
        ],[5.05,2.7,2.7,2.8,3.85],True)
    w.p('¹ Последняя связь в порядке исходной таблицы. У каждого условия 198 выходных токенов. Новых вызовов модели — ноль. Для каждой задачи из заранее сохранённой пары ответов Qwen3.8-27B выбирался один. Правило работало до ответа, используя только вопрос, словарь и уже доступные краткие записи. Разметку открыли после фиксации всех назначений. Прежние агрегаты на этих же задачах были известны.','Caption')
    w.p('Из 84 подробных выдач две исправили ошибку краткого читателя и одна испортила правильный выбор. Во всех 15 сокращённых запросах обе формы выбрали одну и ту же историю. Экономия против постоянного полного текста составила 8 273 токена, по 83,6 на задачу. 95% интервал по репозиториям — от 32,7 до 150,4 сэкономленного токена на задачу. Все четыре изменившихся решения пропущены через условие показа.')
    w.p('При равномерном случайном выборе 84 из 99 вопросов ожидается 74,85 попадания. Вероятность получить 75 или больше составляет 75,61%. Даже если узнать правильный ответ до выбора одной из двух имеющихся формулировок, предел составит 76/99. На этом наборе преимущество правила перед случайным бюджетом обнаружить не удалось.')
    w.p('Словарь из 300 посещённых историй занимал 151 266 байт. Затраты его построения и работы поискового этапа учитываются отдельно от входа Qwen. Здесь проверялся выбор связанной истории. Для оценки успешности последующей правки требуется исполняемый тест.','Caption')
    w.source('Публичные задачи и связи SWE-ContextBench','https://huggingface.co/datasets/jiayuanz3/SWEContextBench')

